 25→+// ResolveCommittedReaderForCheckpoint resolves which committed checkpoint reader
 26→+// should be used for a specific checkpoint ID.
 27→+//
 28→+// Fallback behavior:
 29→+//   - Try v2 first when preferCheckpointsV2 is true
 30→+//   - Fall back to v1 for any v2 failure except context cancellation
 31→+//   - During the v2 migration period, a valid v1 copy should never be blocked
 32→+//     by a corrupt or unreadable v2 copy
 33→+func ResolveCommittedReaderForCheckpoint(
 34→+	ctx context.Context,
 35→+	checkpointID id.CheckpointID,
 36→+	v1Store *GitStore,
 37→+	v2Store *V2GitStore,
 38→+	preferCheckpointsV2 bool,
 39→+) (CommittedReader, *CheckpointSummary, error) {
 40→+	if err := ctx.Err(); err != nil {
 41→+		return nil, nil, err //nolint:wrapcheck // Propagating context cancellation
 42→+	}
 43→+
 44→+	if preferCheckpointsV2 && v2Store != nil {
 45→+		summary, err := v2Store.ReadCommitted(ctx, checkpointID)
 46→+		if err == nil && summary != nil {
 47→+			return v2Store, summary, nil
 48→+		}
 49→+		if err != nil && ctx.Err() != nil {
 50→+			return nil, nil, ctx.Err() //nolint:wrapcheck // Propagating context cancellation
 51→+		}
 52→+		if err != nil && !errors.Is(err, ErrCheckpointNotFound) && !errors.Is(err, ErrNoTranscript) {
 53→+			logging.Debug(ctx, "v2 ReadCommitted failed, falling back to v1",
 54→+				slog.String("checkpoint_id", checkpointID.String()),
 55→+				slog.String("error", err.Error()),
 56→+			)
 57→+		}
 58→+	}
 59→+
 60→+	if v1Store == nil {
 61→+		return nil, nil, ErrCheckpointNotFound
 62→+	}
 63→+
 64→+	summary, err := v1Store.ReadCommitted(ctx, checkpointID)
 65→+	if err != nil {
 66→+		return nil, nil, err
 67→+	}
 68→+	if summary == nil {
 69→+		return nil, nil, ErrCheckpointNotFound
 70→+	}
 71→+
 72→+	return v1Store, summary, nil
 73→+}
