131→+// UpdateSummary persists an AI-generated summary into the latest session's
132→+// metadata on the v2 /main ref. Mirrors GitStore.UpdateSummary for v1.
133→+func (s *V2GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
134→+	if err := ctx.Err(); err != nil {
135→+		return err //nolint:wrapcheck // Propagating context cancellation
136→+	}
137→+
138→+	refName := plumbing.ReferenceName(paths.V2MainRefName)
139→+	parentHash, rootTreeHash, err := s.GetRefState(refName)
140→+	if err != nil {
141→+		return ErrCheckpointNotFound
142→+	}
143→+
144→+	basePath := checkpointID.Path() + "/"
145→+	checkpointPath := checkpointID.Path()
146→+	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
147→+	if err != nil {
148→+		return err
149→+	}
150→+
151→+	rootMetadataPath := basePath + paths.MetadataFileName
152→+	entry, exists := entries[rootMetadataPath]
153→+	if !exists {
154→+		return ErrCheckpointNotFound
155→+	}
156→+
157→+	cpSummary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
158→+	if err != nil {
159→+		return fmt.Errorf("failed to read checkpoint summary: %w", err)
160→+	}
161→+	if len(cpSummary.Sessions) == 0 {
162→+		return ErrCheckpointNotFound
163→+	}
164→+
165→+	latestIndex := len(cpSummary.Sessions) - 1
166→+	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
167→+	sessionEntry, exists := entries[sessionMetadataPath]
168→+	if !exists {
169→+		return fmt.Errorf("session metadata not found at index %d", latestIndex)
170→+	}
171→+
172→+	metadata, err := readJSONFromBlob[CommittedMetadata](s.repo, sessionEntry.Hash)
173→+	if err != nil {
174→+		return fmt.Errorf("failed to read session metadata: %w", err)
175→+	}
176→+	metadata.Summary = redactSummary(summary)
177→+
178→+	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
179→+	if err != nil {
180→+		return fmt.Errorf("failed to marshal metadata: %w", err)
181→+	}
182→+	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
183→+	if err != nil {
184→+		return fmt.Errorf("failed to create metadata blob: %w", err)
185→+	}
186→+	entries[sessionMetadataPath] = object.TreeEntry{
187→+		Name: sessionMetadataPath,
188→+		Mode: filemode.Regular,
189→+		Hash: metadataHash,
190→+	}
191→+
192→+	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, checkpointID, basePath, entries)
193→+	if err != nil {
194→+		return err
195→+	}
196→+
197→+	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
198→+	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, metadata.SessionID)
199→+	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
200→+}
