217→+// ListCommitted lists all committed checkpoints from the v2 /main ref.
218→+// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
219→+func (s *V2GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
220→+	if err := ctx.Err(); err != nil {
221→+		return nil, err //nolint:wrapcheck // Propagating context cancellation
222→+	}
223→+
224→+	refName := plumbing.ReferenceName(paths.V2MainRefName)
225→+	_, rootTreeHash, err := s.GetRefState(refName)
226→+	if err != nil {
227→+		return []CommittedInfo{}, nil //nolint:nilerr // No /main ref means empty list
228→+	}
229→+
230→+	rootTree, err := s.repo.TreeObject(rootTreeHash)
231→+	if err != nil {
232→+		return []CommittedInfo{}, nil //nolint:nilerr // Unreadable tree means no listable entries
233→+	}
234→+
235→+	var checkpoints []CommittedInfo
236→+
237→+	_ = WalkCheckpointShards(s.repo, rootTree, func(checkpointID id.CheckpointID, cpTreeHash plumbing.Hash) error { //nolint:errcheck // callback never returns errors
238→+		checkpointTree, cpTreeErr := s.repo.TreeObject(cpTreeHash)
239→+		if cpTreeErr != nil {
240→+			logging.Debug(ctx, "v2 ListCommitted: skipping unreadable checkpoint tree",
241→+				slog.String("checkpoint_id", checkpointID.String()),
242→+				slog.String("error", cpTreeErr.Error()))
243→+			return nil
244→+		}
245→+
246→+		info := CommittedInfo{CheckpointID: checkpointID}
247→+
248→+		if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
249→+			if content, contentErr := metadataFile.Contents(); contentErr == nil {
250→+				var summary CheckpointSummary
251→+				if unmarshalErr := json.Unmarshal([]byte(content), &summary); unmarshalErr != nil {
252→+					logging.Debug(ctx, "v2 ListCommitted: skipping malformed metadata",
253→+						slog.String("checkpoint_id", checkpointID.String()),
254→+						slog.String("error", unmarshalErr.Error()))
255→+				} else {
256→+					info.CheckpointsCount = summary.CheckpointsCount
257→+					info.FilesTouched = summary.FilesTouched
258→+					info.SessionCount = len(summary.Sessions)
259→+
260→+					if len(summary.Sessions) > 0 {
261→+						latestIndex := len(summary.Sessions) - 1
262→+						latestDir := strconv.Itoa(latestIndex)
263→+						if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
264→+							if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
265→+								if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
266→+									var sessionMetadata CommittedMetadata
267→+									if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
268→+										info.Agent = sessionMetadata.Agent
269→+										info.SessionID = sessionMetadata.SessionID
270→+										info.CreatedAt = sessionMetadata.CreatedAt
271→+									}
272→+								}
273→+							}
274→+						}
275→+					}
276→+				}
277→+			}
278→+		}
279→+
280→+		checkpoints = append(checkpoints, info)
281→+		return nil
282→+	})
283→+
284→+	sort.Slice(checkpoints, func(i, j int) bool {
285→+		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
286→+	})
287→+
288→+	return checkpoints, nil
289→+}
