529→+func listCommittedForExplain(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, preferCheckpointsV2 bool) ([]checkpoint.CommittedInfo, error) {
530→+	v1Committed, v1Err := v1Store.ListCommitted(ctx)
531→+
532→+	if !preferCheckpointsV2 {
533→+		if v1Err != nil {
534→+			return nil, fmt.Errorf("listing v1 checkpoints: %w", v1Err)
535→+		}
536→+		return v1Committed, nil
537→+	}
538→+
539→+	v2Committed, v2Err := v2Store.ListCommitted(ctx)
540→+	if v2Err != nil {
541→+		logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
542→+			slog.String("error", v2Err.Error()),
543→+		)
544→+		if v1Err != nil {
545→+			return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
546→+		}
547→+		return v1Committed, nil
548→+	}
549→+
550→+	if v1Err != nil {
551→+		logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
552→+			slog.String("error", v1Err.Error()),
553→+		)
554→+		return v2Committed, nil
555→+	}
556→+
557→+	// Merge: start with v2, add v1-only entries so pre-v2 checkpoints
558→+	// remain visible during the transition period.
559→+	merged := v2Committed
560→+	seen := make(map[id.CheckpointID]struct{}, len(merged))
561→+	for _, c := range merged {
562→+		seen[c.CheckpointID] = struct{}{}
563→+	}
564→+	for _, c := range v1Committed {
565→+		if _, ok := seen[c.CheckpointID]; !ok {
566→+			merged = append(merged, c)
567→+		}
568→+	}
569→+	return merged, nil
570→+}
