572→+func readLatestSessionContentForExplain(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*checkpoint.SessionContent, error) {
573→+	if summary == nil || len(summary.Sessions) == 0 {
574→+		return nil, checkpoint.ErrCheckpointNotFound
575→+	}
576→+
