578→+	content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
579→+	if err != nil {
580→+		return nil, fmt.Errorf("reading session %d content: %w", latestIndex, err)
581→+	}
582→+	return content, nil
