586→+// metadata, prompts, and the compact transcript (transcript.jsonl). This is the
587→+// primary read path for default display modes that don't need the raw transcript
588→+// stored on /full/* refs.
589→+func readV2ContentFromMain(ctx context.Context, v2Reader *checkpoint.V2GitStore, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*checkpoint.SessionContent, error) {
590→+	if summary == nil || len(summary.Sessions) == 0 {
591→+		return nil, checkpoint.ErrCheckpointNotFound
592→+	}
593→+
594→+	latestIndex := len(summary.Sessions) - 1
595→+
596→+	content, err := v2Reader.ReadSessionMetadataAndPrompts(ctx, checkpointID, latestIndex)
597→+	if err != nil {
