599→+	}
600→+
601→+	compactTranscript, compactErr := v2Reader.ReadSessionCompactTranscript(ctx, checkpointID, latestIndex)
602→+	if compactErr == nil && len(compactTranscript) > 0 {
603→+		content.Transcript = compactTranscript
604→+		content.Metadata.CheckpointTranscriptStart = 0
605→+		content.Metadata.TranscriptLinesAtStart = 0 //nolint:staticcheck // Set for backward compat with older CLI readers
606→+	}
607→+
608→+	return content, nil
